import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { formatDate } from "@/core/formatDate.ts";

const NOW = new Date("2026-06-15T12:00:00Z");
const ago = (ms: number): Date => new Date(NOW.getTime() - ms);

const SECOND = 1000;
const MINUTE = 60 * SECOND;
const HOUR   = 60 * MINUTE;
const DAY    = 24 * HOUR;

describe("formatDate", () => {

  beforeEach(() => { vi.useFakeTimers(); vi.setSystemTime(NOW); });
  afterEach(() => { vi.useRealTimers(); });

  it.each([
    [ 30 * SECOND, "30 seconds ago"]
  , [  5 * MINUTE, "5 minutes ago"]
  , [  3 * HOUR,   "3 hours ago"]
  , [  3 * DAY,    "3 days ago"]
  , [ 14 * DAY,    "2 weeks ago"]
  , [ 90 * DAY,    "3 months ago"]
  , [800 * DAY,    "2 years ago"]
  ])("formats an age of %i ms as '%s'", (age, expected) => {
    expect(formatDate(ago(age))).toBe(expected);
  });

  it("uses the `numeric: auto` wording for exactly one unit", () => {
    expect(formatDate(ago(DAY))).toBe("yesterday");
  });

  it("says 'now' for the current instant", () => {
    expect(formatDate(NOW)).toBe("now");
  });

  it("never produces a nonsensical unit at the minute/hour boundary", () => {
    // 59.5 minutes rounds to 60 minutes, which must roll over to an hour rather than print "60 minutes ago"
    expect(formatDate(ago(59.5 * MINUTE))).not.toMatch(/60 minutes/);
  });

  it("describes a timestamp slightly in the future (client/server clock skew) as upcoming, not as a crash", () => {
    expect(formatDate(new Date(NOW.getTime() + 5 * SECOND))).toBe("in 5 seconds");
  });

});
